// ContentView.swift — the VisiCalc UI host shell (VC2-swiftui).
//
// Mounts the auto-generated FormulaBarView above a hand-written
// 5×5 grid. State is held in a `@State` model that pretends to be
// the host's reducer.
//
// Same hard-coded 5×5 sample data as the other VC2-* demos so the
// SwiftUI render matches React, HTML, WebComponent, Flutter, Qt
// visually.

import SwiftUI

struct ContentView: View {
    // 5×5 sample spreadsheet — same data as VC2-html / VC2-webcomp /
    // VC2-flutter / VC2-qt.
    static let sampleRows: [[String]] = [
        ["15", "3",  "12", "8",  "5"],
        ["8",  "14", "7",  "22", "11"],
        ["12", "9",  "18", "6",  "25"],
        ["4",  "11", "3",  "17", "9"],
        ["7",  "5",  "13", "10", "19"],
    ]

    @State private var selectedRow: Int = 0
    @State private var selectedCol: Int = 0
    @State private var formula: String = "=SUM(B1:B5)"

    private var cellAddress: String {
        let colLetter = Character(UnicodeScalar(65 + UInt32(selectedCol))!)
        return "\(colLetter)\(selectedRow + 1)"
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 0) {
            Text("VISICALC · MOSAIC SWIFTUI DEMO")
                .font(.system(size: 11))
                .tracking(1.0)
                .foregroundColor(Color(hex: 0x9D9D9D))
                .padding([.top, .leading, .trailing], 16)
                .padding(.bottom, 8)

            // FormulaBar — generated by mosaic-compile.
            FormulaBarView(
                cellAddress: cellAddress,
                formula: formula,
                readOnly: false,
                dispatch: handleFormulaBarEvent
            )

            // Grid — hand-written placeholder until the SwiftUI Grid
            // emitter learns the `Grid` built-in primitive.
            GridView(
                columnHeaders: ["A", "B", "C", "D", "E"],
                viewportRows: ContentView.sampleRows,
                selectedRow: selectedRow,
                selectedCol: selectedCol,
                onTapCell: { r, c in
                    selectedRow = r
                    selectedCol = c
                    formula = ContentView.sampleRows[r][c]
                }
            )
            .padding(16)

            Spacer()
        }
        .frame(maxWidth: 720, maxHeight: .infinity, alignment: .topLeading)
        .background(Color(hex: 0x1E1E1E))
        .preferredColorScheme(.dark)
    }

    private func handleFormulaBarEvent(_ event: FormulaBarEvent) {
        switch event {
        case .formulaChange(let value):
            formula = value
        case .commit:
            break // no-op for v1
        case .cancel:
            formula = ContentView.sampleRows[selectedRow][selectedCol]
        }
    }
}

// Helper init for hex colours so we don't have to write
// `Color(red:, green:, blue:)` everywhere.
extension Color {
    init(hex: UInt32) {
        let r = Double((hex >> 16) & 0xFF) / 255.0
        let g = Double((hex >> 8) & 0xFF) / 255.0
        let b = Double(hex & 0xFF) / 255.0
        self.init(red: r, green: g, blue: b)
    }
}
